UPDATE courses SET
    course_description = '<div> <div> <div> <div> <p>This qualification reflects the role of individuals in the accounting and bookkeeping industry, including business activity statement (BAS) agents and contract bookkeepers; and of those employees performing bookkeeping tasks for organisations in a range of industries. It includes preparing and lodging business and instalment activity statements, data processing, monthly reconciliations, preparing budgets, preparing reports on financial performance and the position of the business, preparing end-of-year adjustments, and finalising financial records after year-end. Dealing with the Commissioner of Taxation on behalf of a taxpayer in relation to activity statements and other lodgement matters is also a key component of the role that this qualification reflects. Individuals in these roles apply theoretical and specialist skills and knowledge to work autonomously, and exercise judgement in completing routine and non-routine activities.</p> </div> </div> </div> </div>',
    course_duration_per_week = 78,
    offshore_tuition_fee = 18000,
    onshore_tuition_fee = 18000,
    enrolment_fee = 250,
    materials_fee = 450,
