    apply_form = 'https://rockford.edu.au/course/fns40222-certificate-iv-in-accounting-and-bookkeeping/',
    updated_at = NOW()
WHERE cricos_course_code = '110023M';
UPDATE courses SET
    course_description = '<div> <div> <div> <div> <p>The General English course is designed to prepare students for conversation, everyday situations and daily interactions that take place when traveling or living in an English-speaking country. Students learn and practice the four macro-skills of listening, reading, writing and speaking in an interactive environment. Levels of difficulty increase over the duration of the course to assist students to develop their skills and to be more confident and fluent in English.</p> </div> </div> </div> </div>',
    course_duration_per_week = 80,
    offshore_tuition_fee = 15000,
    onshore_tuition_fee = 15000,
    enrolment_fee = 250,
    materials_fee = 600,
    entry_requirements = '<h4>Entry Requirements</h4><div> <div> <div> <div> <ul><li>Must be 18 years of age or older.</li> <li>Participate in the English Placement Test and an interview.</li> <li>Participate in the Course Entry Requirement Interview.</li> <li>International Students must meet the Student Visa (SC500) requirements.</li> </ul></div> </div> </div> </div>',
    apply_form = 'https://rockford.edu.au/course/general-english/',
