UPDATE courses SET
    course_description = '<div> <div> <div> <div> <p>This qualification reflects the role of individuals in a variety of information and communications technology (ICT) roles who have established specialised skills in a technical ICT function.</p> <p>Individuals in these roles carry out moderately complex tasks in a specialist field, working independently, as part of a team or leading a deliverable with others. They may apply their skills across a wide range of industries, business functions and departments, or as a business owner (sole trader/contractor).</p> <p>The skills required for these roles may include, but are not restricted to:</p> <p>advanced networking: configuring and managing virtual computing environments, and security within ICT networks<br/> advanced programming: applying intermediate and advanced programming skills, managing data and building advanced user interfaces to manage organizational requirements<br/> back end web development: developing and maintaining website information architecture and data<br/> business analysis: designing and implementing technical requirements, quality assurance processes, and contingency plans for businesses<br/> cloud architecture: developing, improving and designing cloud infrastructure, including disaster recovery plans<br/> cloud engineering: building, implementing and managing cloud infrastructure and virtual networks<br/> cybersecurity: protecting sensitive data and information through security architecture and developing disaster recovery and contingency plans<br/> database and data management: creating, designing and monitoring systems that store data and optimize organisational knowledge management<br/> front end web development: designing dynamic and complex websites, user experience solutions and documents using extensible mark-up languages<br/> game art and design: creating complex 2D and 3D modelling and animation software through scripts and storyboards<br/> game programming: creating complex 2D and 3D interactive games and media, building graphical user interfaces, and applying artificial intelligence in game development<br/> systems administration: reviewing maintenance procedures and support to help troubleshoot system applications<br/> systems analysis: modelling and testing data objects, data processes and preferred ICT system solutions<br/> telecommunications network engineering: managing logistics, organisational specifications, regulations, and legislative requirements across network projects.</p> </div> </div> </div> </div>',
    course_duration_per_week = 78,
    offshore_tuition_fee = 18000,
    onshore_tuition_fee = 18000,
    enrolment_fee = 250,
    materials_fee = 450,
    entry_requirements = '<h4>Entry Requirements</h4><div> <div> <div> <div> <p>Entry Requirement<br/> Must be 18 years of age or older.<br/> Must provide proof of school studies which is equivalent to Australian Year 12 or other higher qualifications.<br/> Must provide valid academic IELTS* score of 6.0 overall with no band less than 5.5 or equivalent unless exempted or need to submit English Proficiency certificate from an approved ELICOS provider of upper intermediate level or above; or completion of substantial part of studies of at least an AQF Certificate IV qualification or higher within the last 2 years; or have successfully passed the Rockford College English Placement Test. For further details; please refer to the Department of Home Affairs (DOHA) website for Acceptable English and Exemptions.<br/> Participate in the Course Entry Requirement Interview.<br/> International Students must meet the Student Visa (SC500) requirements.</p> <p>* Note that other English Language Test such as PTE and TOEFL can be accepted.</p> </div> </div> </div> </div>',
    apply_form = 'https://rockford.edu.au/course/ict50220-diploma-of-information-technology/',
    updated_at = NOW()
WHERE cricos_course_code = '105702H';
UPDATE courses SET
    course_description = '<div> <div> <div> <div> <p>This qualification reflects the role of individuals in a variety of information and communications technology (ICT) roles who have significant experience in specialist technical skills, or managerial business and people management skills.</p> <p>Individuals in these roles carry out complex tasks in a specialist field, working independently, leading a team or a strategic direction of a business. They apply their skills across a wide range of industries and business functions, or as a business owner (sole trader/contractor).</p> <p>The skills required for these roles may include, but are not restricted to:</p> <ul><li>advanced data management information: creating, designing and monitoring complex systems that store data, and optimising organisational knowledge management</li> <li>cyber security: protecting sensitive data and information through security architecture, and developing disaster recovery and contingency plans</li> <li>full stack web development: building advanced user interfaces, developing representational state transfer application program interfaces (REST APIs) and designing user experience solutions</li> <li>further programming: applying advanced ICT languages to maintain security and manage data</li> <li>IT strategy and organisational development: managing and communicating strategic ICT business solutions</li> <li>systems development and analysis: modelling and testing data objects, data processes and preferred ICT system solutions</li> <li>telecommunications network engineering: managing logistics, organisational specifications, regulations and legislative requirements across network projects.</li> </ul></div> </div> </div> </div>',
    course_duration_per_week = 78,
    offshore_tuition_fee = 18000,
    onshore_tuition_fee = 18000,
    enrolment_fee = 250,
    materials_fee = 450,
    entry_requirements = '<h4>Entry Requirements</h4><div> <div> <div> <div> <ul><li>Must be 18 years of age or older.</li> <li>Must provide proof of school studies which is equivalent to Australian Year 12 or other higher qualifications.</li> <li>Must provide valid academic IELTS* score of 6.0 overall with no band less than 5.5 or equivalent unless exempted or need to submit English Proficiency certificate from an approved ELICOS provider of upper intermediate level or above; or completion of substantial part of studies of at least an AQF Certificate IV qualification or higher within the last 2 years; or have successfully passed the Rockford College English Placement Test. For further details; please refer to the Department of Home Affairs (DOHA) website for Acceptable English and Exemptions.</li> <li>Participate in the Course Entry Requirement Interview.</li> <li>International Students must meet the Student Visa (SC500) requirements.</li> </ul><p>* Note that other English Language Test such as PTE and TOEFL can be accepted.</p> </div> </div> </div> </div>',
    apply_form = 'https://rockford.edu.au/course/ict60220-advanced-diploma-of-information-technology/',
    updated_at = NOW()
WHERE cricos_course_code = '105703G';
UPDATE courses SET
    course_description = '<div> <div> <div> <div> <p>This qualification reflects the role of individuals working as designers or design paraprofessionals who support professional engineers. They perform tasks involving a high level of autonomy and requiring the application of significant judgement in planning and determining the selection of equipment/roles/techniques for themselves and others. They are required to develop site specific work designs to ensure the implementation of the client’s site requirements. They demonstrate the application of a broad range of technical, managerial, coordination and planning skills.</p> </div> </div> </div> </div>',
    course_duration_per_week = 52,
    offshore_tuition_fee = 12000,
    onshore_tuition_fee = 12000,
    enrolment_fee = 250,
    materials_fee = 1000,
    entry_requirements = '<h4>Entry Requirements</h4><div> <div> <div> <div> <ul><li>Must be 18 years of age or older.</li> <li>Must provide proof of school studies which is equivalent to Australian Year 12 or other higher qualifications.</li> <li>Must provide valid academic IELTS* of at least 6.0 overall with no band less than 5.5 or equivalent unless exempted or need to submit English Proficiency certificate from an approved ELICOS provider of upper-intermediate level or above; or completion of substantial part of studies of at least an AQF Certificate IV qualification or higher within the last 2 years; or have successfully passed the Rockford College English Placement Test. For further details; please refer to the Department of Home Affairs (DOHA) website for Acceptable English and Exemptions.</li> <li>Participate in the Course Entry Requirement Interview.</li> <li>International Students must meet the Student Visa (SC500) requirements.<br/> * Note that other English language tests such as PTE and TOEFL can be accepted. Students are required to provide their results so that it can be confirmed they are equivalent to IELTS 6.0.</li> </ul></div> </div> </div> </div>',
    apply_form = 'https://rockford.edu.au/course/rii50520-diploma-of-civil-construction-design/',
    updated_at = NOW()
WHERE cricos_course_code = '120671G';
